The BSOD is caused by a **direct write to the read‑only SSDT table**:

```cpp
ServiceTableBase[ SyscallNum ] = SsdtEntry;   // ← CRASH
```

On Windows 10 19045, the SSDT is mapped **read‑only in the page tables**.  
Even with interrupts disabled (`WPOFF`), the CPU will fault on the write.

The fix is to **MDL‑map the exact SSDT entry** before writing – the same technique already used for the code cave.  
You’ll change both `HookSSDT` and `UnhookSSDT` (and later the shadow equivalents).

---

### 🔧 Modified `HookSSDT` function (replace the whole function)

```cpp
bool HookSSDT( PUCHAR pCode, ULONG ulCodeSize, PVOID pNewFunction, PVOID* pOldFunction, ULONG SyscallNum )
{
    if ( !pNewFunction || !pOldFunction || SyscallNum <= 0 )
        return false;

    DBGPRINT( "[ HookSSDT ] Syscall: 0x%X\n", SyscallNum );

    *pOldFunction = PVOID( GetSSDTFuncCurAddr64( SyscallNum ) );
    DBGPRINT( "[ HookSSDT ] Original: 0x%p\n", *pOldFunction );

    *( PULONG64 )( jmp_trampoline + 3 ) = ULONG64( pNewFunction );

    auto pCodeCave = utils::FindCodeCave( pCode, ulCodeSize, sizeof( jmp_trampoline ) );
    if ( !pCodeCave )
    {
        DBGPRINT( "[ HookSSDT ] Failed to find a suitable code cave.\n" );
        return false;
    }

    DBGPRINT( "[ HookSSDT ] Code Cave: 0x%p\n", pCodeCave );

    // MDL for the code cave (already exists)
    auto Mdl = IoAllocateMdl( pCodeCave, sizeof( jmp_trampoline ), 0, 0, NULL );
    if ( Mdl == NULL )
    {
        DBGPRINT( "[ HookSSDT ] IoAllocateMdl failed!\n" );
        return false;
    }

    MmProbeAndLockPages( Mdl, KernelMode, IoWriteAccess );

    auto Mapping = MmMapLockedPagesSpecifyCache( Mdl, KernelMode, MmCached, NULL, FALSE, NormalPagePriority );
    if ( Mapping == NULL )
    {
        MmUnlockPages( Mdl );
        IoFreeMdl( Mdl );
        DBGPRINT( "[ HookSSDT ] MmMapLockedPagesSpecifyCache failed!\n" );
        return false;
    }

    auto ServiceTableBase = ( PULONG )g_KeServiceDescriptorTable->ServiceTableBase;

    auto irql = utils::WPOFF();

    // Copy the trampoline into the code cave
    RtlCopyMemory( Mapping, jmp_trampoline, sizeof( jmp_trampoline ) );

    // Compute the new SSDT entry value
    auto SsdtEntry = GetOffsetAddress( ULONG64( pCodeCave ) );
    SsdtEntry &= 0xFFFFFFF0;
    SsdtEntry += ServiceTableBase[ SyscallNum ] & 0x0F;

    // --- MDL‑map the SSDT entry itself to make it writable ---
    PULONG pSsdtAddr = &ServiceTableBase[ SyscallNum ];
    MDL* pSsdtMdl = IoAllocateMdl( pSsdtAddr, sizeof( ULONG ), FALSE, FALSE, NULL );
    if ( pSsdtMdl )
    {
        MmProbeAndLockPages( pSsdtMdl, KernelMode, IoWriteAccess );
        PULONG pMappedSsdt = ( PULONG )MmMapLockedPagesSpecifyCache( pSsdtMdl, KernelMode, MmCached, NULL, FALSE, NormalPagePriority );
        if ( pMappedSsdt )
        {
            *pMappedSsdt = SsdtEntry;                         // safe write
            MmUnmapLockedPages( pMappedSsdt, pSsdtMdl );
        }
        MmUnlockPages( pSsdtMdl );
        IoFreeMdl( pSsdtMdl );
    }
    // -----------------------------------------------------------

    utils::WPON( irql );

    MmUnmapLockedPages( Mapping, Mdl );
    MmUnlockPages( Mdl );
    IoFreeMdl( Mdl );

    return true;
}
```

