            // The next 4 bytes are a relative offset to the SSDT structure
            INT32 relOffset = *(PINT32)(start + i + 3);
            ULONGLONG ssdtAddr = (ULONGLONG)(start + i + 7) + relOffset;
            DBGPRINT("Found KeServiceDescriptorTable at 0x%p (offset from KiSystemServiceRepeat)\n", ssdtAddr);
            return ssdtAddr;
