// Global recursion guard – prevents the hook from calling itself
static volatile LONG g_HookActive = 0;

NTSTATUS NTAPI hkNtQuerySystemInformation(
    SYSTEM_INFORMATION_CLASS SystemInformationClass,
    PVOID Buffer,
    ULONG Length,
    PULONG ReturnLength )
{
    // ---------- Recursion guard ----------
    if (InterlockedExchange(&g_HookActive, 1) == 1)
    {
        // Already inside this hook – call original directly to avoid stack overflow
        DBGPRINT("[hkNtQuerySystemInformation] REENTRY DETECTED – calling original directly\n");
        return oNtQuerySystemInformation(SystemInformationClass, Buffer, Length, ReturnLength);
    }

    NTSTATUS ret = oNtQuerySystemInformation(SystemInformationClass, Buffer, Length, ReturnLength);
    DBGPRINT("[hkNtQuerySystemInformation] Called class=0x%X Status=0x%X\n", SystemInformationClass, ret);

    // If we are a protected process, don't filter – return immediately
    if (tools::IsProtectedProcess(PsGetCurrentProcessId()))
    {
        DBGPRINT("[hkNtQuerySystemInformation] Current process is protected, skipping filter\n");
        InterlockedExchange(&g_HookActive, 0);
        return ret;
    }

    if (!NT_SUCCESS(ret))
    {
        InterlockedExchange(&g_HookActive, 0);
        return ret;
    }

    __try
    {
        // -------- Hide Drivers (SystemModuleInformation) --------
        if (SystemInformationClass == SystemModuleInformation)
        {
            DBGPRINT("[hkNtQuerySystemInformation] Processing SystemModuleInformation\n");
            auto pModule = (PRTL_PROCESS_MODULES)Buffer;
            for (ULONG i = 0; i < pModule->NumberOfModules; i++)
            {
                // Check driver name
                for (int x = 0; x < ARRAYSIZE(globals::szProtectedDrivers); x++)
                {
                    if (strstr((char*)pModule->Modules[i].FullPathName, globals::szProtectedDrivers[x]))
                    {
                        DBGPRINT("[hkNtQuerySystemInformation] Hiding driver %s\n", pModule->Modules[i].FullPathName);
                        if ((i + 1) < pModule->NumberOfModules)
                        {
                            RtlMoveMemory(&pModule->Modules[i], &pModule->Modules[i+1],
                                          (pModule->NumberOfModules - i - 1) * sizeof(RTL_PROCESS_MODULE_INFORMATION));
                        }
                        RtlZeroMemory(&pModule->Modules[pModule->NumberOfModules - 1], sizeof(RTL_PROCESS_MODULE_INFORMATION));
                        pModule->NumberOfModules--;
                        i--; // re-check the shifted entry
                    }
                }
            }
        }
        // -------- Hide Processes --------
        else if (SystemInformationClass == SystemProcessInformation ||
                 SystemInformationClass == SystemSessionProcessInformation ||
                 SystemInformationClass == SystemExtendedProcessInformation)
        {
            DBGPRINT("[hkNtQuerySystemInformation] Processing process list\n");

            // Ensure the buffer contains at least one entry
            if (Length < sizeof(SYSTEM_PROCESS_INFORMATION))
            {
                DBGPRINT("[hkNtQuerySystemInformation] Buffer too small for process list\n");
                __leave;
            }

            PSYSTEM_PROCESS_INFO pCurr = NULL;
            PSYSTEM_PROCESS_INFO pNext = (PSYSTEM_PROCESS_INFO)Buffer;
            ULONG_PTR bufferEnd = (ULONG_PTR)Buffer + Length;

            // Check the very first entry
            if (pNext->ImageName.Buffer && tools::IsProtectedProcess(pNext->ImageName.Buffer))
            {
