                                    CsrId = (HANDLE)pHandles->Information[i].ProcessId;
                            }
                        }
                    }
                    ZwClose(hObject);
                }
                ZwClose(Process);
            }
        }
        ExFreePoolWithTag(pHandles, TAG);
    }
    return CsrId;
}

