		}
		MmUnlockPages( pSsdtMdl );
		IoFreeMdl( pSsdtMdl );
	}
	// ----------------------------------------------------

	utils::WPON( irql );

	//
	// Restore protection for the code cave
	//
	MmUnmapLockedPages( Mapping, Mdl );
	MmUnlockPages( Mdl );
	IoFreeMdl( Mdl );

	return true;
}

