### 5. Full corrected `HookSSSDT` with all fixes

Below is the entire function ready to copy‑paste over the existing one in `shadow_ssdt.cpp`.  
It includes the **+0x1000 offset**, all the debug prints, and the corrected strings / casts / trampoline size variable.

```cpp
bool HookSSSDT( PUCHAR pCode, ULONG ulCodeSize, PVOID pNewFunction, PVOID* pOldFunction, ULONG SyscallNum )
{
	if ( !pNewFunction || !pOldFunction || SyscallNum <= 0 )
		return false;

	ULONGLONG				W32pServiceTable = 0, qwTemp = 0;
	LONG 					dwTemp = 0;
	KIRQL					irql;

	DBGPRINT( "[ HookSSSDT ] Syscall: 0x%X\n", SyscallNum );

	*pOldFunction = PVOID( GetSSSDTFuncCurAddr64( SyscallNum ) );
	DBGPRINT( "[ HookSSSDT ] Original: 0x%p\n", *pOldFunction );

	*( PULONG64 )( jmp_trampoline + 3 ) = ULONG64( pNewFunction );

	const ULONG trampolineSize = sizeof( jmp_trampoline );

	DBGPRINT( "[ HookSSSDT ] Searching for code cave...\n" );
	auto pCodeCave = utils::FindCodeCave( pCode + 0x1000, ulCodeSize - 0x1000, trampolineSize );
	if ( !pCodeCave )
	{
		DBGPRINT( "[ HookSSSDT ] Failed to find a suitable code cave.\n" );
		return false;
	}
	DBGPRINT( "[ HookSSSDT ] Code Cave: 0x%p\n", pCodeCave );

	DBGPRINT( "[ HookSSSDT ] Allocating MDL for code cave...\n" );
	auto Mdl = IoAllocateMdl( pCodeCave, trampolineSize, 0, 0, NULL );
	if ( Mdl == NULL )
	{
		DBGPRINT( "[ HookSSSDT ] IoAllocateMdl failed!\n" );
		return false;
	}
	DBGPRINT( "[ HookSSSDT ] Mdl allocated: 0x%p\n", Mdl );

	DBGPRINT( "[ HookSSSDT ] Probing and locking pages for code cave...\n" );
	MmProbeAndLockPages( Mdl, KernelMode, IoReadAccess );
	DBGPRINT( "[ HookSSSDT ] Pages locked.\n" );

	DBGPRINT( "[ HookSSSDT ] Mapping locked pages for code cave...\n" );
	auto Mapping = MmMapLockedPagesSpecifyCache( Mdl, KernelMode, MmCached, NULL, FALSE, NormalPagePriority );
	if ( Mapping == NULL )
	{
		DBGPRINT( "[ HookSSSDT ] MmMapLockedPagesSpecifyCache failed!\n" );
		MmUnlockPages( Mdl );
		IoFreeMdl( Mdl );
		return false;
	}
	DBGPRINT( "[ HookSSSDT ] Code cave mapped at: 0x%p\n", Mapping );

	DBGPRINT( "[ HookSSSDT ] Disabling write protection...\n" );
	irql = utils::WPOFF();
	DBGPRINT( "[ HookSSSDT ] WP off, copying trampoline...\n" );

	RtlCopyMemory( Mapping, jmp_trampoline, trampolineSize );
	DBGPRINT( "[ HookSSSDT ] Trampoline copied. Calculating SSSDT entry...\n" );

	W32pServiceTable = ( ULONGLONG )( g_KeServiceDescriptorTableShadow->ServiceTableBase );
	qwTemp = W32pServiceTable + 4 * ( SyscallNum - 0x1000 );
	dwTemp = ( LONG )( ( ULONG64 )pCodeCave - W32pServiceTable );
	dwTemp = dwTemp << 4;
	DBGPRINT( "[ HookSSSDT ] SSSDT entry address: 0x%p, new value: 0x%X\n", (PVOID)qwTemp, (ULONG)dwTemp );

	DBGPRINT( "[ HookSSSDT ] Allocating MDL for SSSDT entry...\n" );
	MDL* pSsdtMdl = IoAllocateMdl( (PVOID)qwTemp, sizeof(LONG), FALSE, FALSE, NULL );
	if ( pSsdtMdl )
	{
		DBGPRINT( "[ HookSSSDT ] SSSDT MDL allocated: 0x%p\n", pSsdtMdl );
		DBGPRINT( "[ HookSSSDT ] Probing and locking SSSDT page...\n" );
		MmProbeAndLockPages( pSsdtMdl, KernelMode, IoReadAccess );
		DBGPRINT( "[ HookSSSDT ] SSSDT page locked. Mapping...\n" );

		PLONG pMappedSsdt = (PLONG)MmMapLockedPagesSpecifyCache( pSsdtMdl, KernelMode, MmCached, NULL, FALSE, NormalPagePriority );
		if ( pMappedSsdt )
		{
			DBGPRINT( "[ HookSSSDT ] SSSDT mapped at: 0x%p. Writing...\n", pMappedSsdt );
			*pMappedSsdt = dwTemp;
			DBGPRINT( "[ HookSSSDT ] Write successful.\n" );
			MmUnmapLockedPages( pMappedSsdt, pSsdtMdl );
		}
		else
		{
			DBGPRINT( "[ HookSSSDT ] MmMapLockedPagesSpecifyCache for SSSDT failed!\n" );
		}
		MmUnlockPages( pSsdtMdl );
		IoFreeMdl( pSsdtMdl );
	}
	else
	{
		DBGPRINT( "[ HookSSSDT ] IoAllocateMdl for SSSDT failed!\n" );
	}

	DBGPRINT( "[ HookSSSDT ] Re-enabling write protection...\n" );
	utils::WPON( irql );

	DBGPRINT( "[ HookSSSDT ] Cleaning up code cave mappings...\n" );
	MmUnmapLockedPages( Mapping, Mdl );
	MmUnlockPages( Mdl );
	IoFreeMdl( Mdl );

	DBGPRINT( "[ HookSSSDT ] HookSSSDT complete.\n" );
	return true;
}
```

